parameters.jsCode:
const form = $('When SEO Audit Requested').item.json;
const url = String(form['Page URL'] || '').trim();
const sig = $('Extract SEO Data').item.json;
const robotsStatus = $json.statusCode ?? 0;
const robotsBody = typeof $json.body === 'string' ? $json.body : '';
const robotsFound = robotsStatus >= 200 && robotsStatus < 300 && !/<html/i.test(robotsBody);
const hasSitemap = robotsFound && /sitemap\s*:/i.test(robotsBody);

const title = String(sig.pageTitle || '').trim();
const meta = String(sig.metaDescription || '').trim();
const h1s = Array.isArray(sig.h1) ? sig.h1 : (sig.h1 ? [sig.h1] : []);
const h2s = Array.isArray(sig.h2) ? sig.h2 : (sig.h2 ? [sig.h2] : []);
const words = String(sig.bodyText || '').trim().split(/\s+/).filter(Boolean).length;
const imgAlts = Array.isArray(sig.imgAlt) ? sig.imgAlt : [];
const missingAlt = imgAlts.filter((a) => !String(a || '').trim()).length;
const canonical = String(sig.canonical || '').trim();

const checks = [];
const add = (check, status, result) => checks.push({ check, status, result });
add('Served over HTTPS', url.startsWith('https://') ? 'pass' : 'fail', url.split('/').slice(0, 3).join('/'));
add('Title tag present', title ? 'pass' : 'fail', title ? '"' + title.slice(0, 80) + '"' : 'missing');
add('Title length 30-60 chars', title.length >= 30 && title.length <= 60 ? 'pass' : title.length > 0 ? 'warn' : 'fail', title.length + ' chars');
add('Meta description present', meta ? 'pass' : 'fail', meta ? 'present' : 'missing');
add('Meta description 70-160 chars', meta.length >= 70 && meta.length <= 160 ? 'pass' : meta.length > 0 ? 'warn' : 'fail', meta.length + ' chars');
add('Exactly one H1', h1s.length === 1 ? 'pass' : h1s.length > 1 ? 'warn' : 'fail', h1s.length + ' found');
add('At least two H2s', h2s.length >= 2 ? 'pass' : h2s.length === 1 ? 'warn' : 'fail', h2s.length + ' found');
add('300+ words of body copy', words >= 300 ? 'pass' : words >= 120 ? 'warn' : 'fail', words + ' words');
add('All images have alt text', imgAlts.length === 0 ? 'warn' : missingAlt === 0 ? 'pass' : 'fail', imgAlts.length === 0 ? 'no images detected' : missingAlt + ' of ' + imgAlts.length + ' missing');
add('Canonical URL declared', canonical ? 'pass' : 'warn', canonical || 'missing');
add('robots.txt found', robotsFound ? 'pass' : 'warn', 'HTTP ' + robotsStatus);
add('Sitemap declared in robots.txt', hasSitemap ? 'pass' : 'warn', robotsFound ? (hasSitemap ? 'declared' : 'not declared') : 'no robots.txt');

const per = 100 / checks.length;
const score = Math.round(checks.reduce((s, c) => s + (c.status === 'pass' ? per : c.status === 'warn' ? per / 2 : 0), 0));
const failed = checks.filter((c) => c.status !== 'pass').map((c) => c.check);
return [{ json: { url, score, checks, failed, words, h1Count: h1s.length, h2Count: h2s.length } }];

